function showChartTip(target,x,y){chartTooltip.textContent=target.dataset.chartTip;chartTooltip.classList.add('visible');const width=chartTooltip.offsetWidth;chartTooltip.style.left=`${Math.max(8,Math.min(x+14,window.innerWidth-width-8))}px`;chartTooltip.style.top=`${Math.max(8,y-48)}px`}
main.addEventListener('pointermove',event=>{const target=event.target.closest?.('[data-chart-tip]');if(target)showChartTip(target,event.clientX,event.clientY);else chartTooltip.classList.remove('visible')});
