let vo2Selection=[];
function vo2GapLabel(a,b){
  const [start,end]=[a,b].sort();
  const from=new Date(`${start}T00:00:00Z`),to=new Date(`${end}T00:00:00Z`);
  const days=Math.round((to-from)/86400000);
  let months=(to.getUTCFullYear()-from.getUTCFullYear())*12+to.getUTCMonth()-from.getUTCMonth();
  if(to.getUTCDate()<from.getUTCDate())months--;
  if(months<1){const weeks=Math.max(1,Math.round(days/7));return `${weeks} ${weeks===1?'week':'weeks'} apart`}
  if(months<12)return `${months} ${months===1?'month':'months'} apart`;
  const years=Math.floor(months/12),remainder=months%12;
  return `${years} ${years===1?'year':'years'}${remainder?` ${remainder} ${remainder===1?'month':'months'}`:''} apart`;
}
function selectVo2Point(target){
  const point=target.closest?.('[data-vo2-point]');
  if(!point)return;
  const existing=vo2Selection.findIndex(selected=>selected.dataset.vo2Point===point.dataset.vo2Point);
  if(existing>=0)vo2Selection.splice(existing,1);
  else{if(vo2Selection.length===2)vo2Selection=[];vo2Selection.push(point)}
  main.querySelectorAll('[data-vo2-point]').forEach(dot=>dot.classList.toggle('selected',vo2Selection.includes(dot)));
  const output=main.querySelector('#vo2-comparison');
  if(!output)return;
  output.hidden=vo2Selection.length===0;
  if(!vo2Selection.length)return;
  const fromValue=output.querySelector('.vo2-from-value'),toValue=output.querySelector('.vo2-to-value'),delta=output.querySelector('.vo2-delta'),gap=output.querySelector('.vo2-gap');
  if(vo2Selection.length===1){fromValue.textContent=Number(vo2Selection[0].dataset.vo2Value).toFixed(1);toValue.textContent='—';delta.textContent='';gap.textContent='Select another dot';return}
  const [first,second]=vo2Selection;
  const from=Number(first.dataset.vo2Value),to=Number(second.dataset.vo2Value),change=to-from;
  fromValue.textContent=from.toFixed(1);
  toValue.textContent=to.toFixed(1);
  delta.textContent=`${change>=0?'+':''}${change.toFixed(1)} mL/kg/min`;
  gap.textContent=vo2GapLabel(first.dataset.vo2Date,second.dataset.vo2Date);
}
main.addEventListener('click',event=>selectVo2Point(event.target));
main.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.closest?.('[data-vo2-point]')){event.preventDefault();selectVo2Point(event.target)}});
let paceSelection=[];
function selectPacePoint(target){
  const point=target.closest?.('[data-pace-point]');
  if(!point)return;
  const existing=paceSelection.findIndex(selected=>selected.dataset.pacePoint===point.dataset.pacePoint);
  if(existing>=0)paceSelection.splice(existing,1);
  else{if(paceSelection.length===2)paceSelection=[];paceSelection.push(point)}
  main.querySelectorAll('[data-pace-point]').forEach(dot=>dot.classList.toggle('selected',paceSelection.includes(dot)));
  const output=main.querySelector('#pace-comparison');
  if(!output)return;
  output.hidden=paceSelection.length===0;
  if(!paceSelection.length)return;
  const fromValue=output.querySelector('.vo2-from-value'),toValue=output.querySelector('.vo2-to-value'),delta=output.querySelector('.vo2-delta'),gap=output.querySelector('.vo2-gap');
  const first=paceSelection[0],from=Number(first.dataset.paceValue);
  fromValue.textContent=paceLabel(from);
  if(paceSelection.length===1){toValue.textContent='—';delta.textContent='';gap.textContent='Select another dot';return}
  const second=paceSelection[1],to=Number(second.dataset.paceValue),difference=Math.round(Math.abs(to-from));
  toValue.textContent=paceLabel(to);
  delta.textContent=difference===0?'Same pace':`${difference} sec ${to<from?'faster':'slower'} /km`;
  gap.textContent=vo2GapLabel(first.dataset.paceDate,second.dataset.paceDate);
}
main.addEventListener('click',event=>selectPacePoint(event.target));
main.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.closest?.('[data-pace-point]')){event.preventDefault();selectPacePoint(event.target)}});
let state={program:[],baselines:[],activities:[],runs:[],rides:[],vo2Readings:[]};
let view='home';
