const yearAnchor=()=>selectedYear===new Date().getFullYear()?todayISO():`${selectedYear}-12-31`;
let workoutDay=null;
let workoutDate=null;
let enduranceEdit=null;
let runningFormOpen=false;
let cyclingFormOpen=false;
