  const vo2Raw=[...(state.vo2Readings||[]).filter(inSelectedYear).map(x=>({date:x.date,value:x.value})),...[...runs,...rides].filter(x=>Number.isFinite(x.vo2max)).map(x=>({date:x.date,value:x.vo2max}))];
  const vo2Weeks=new Map();for(const reading of vo2Raw){const week=localISO(weekStart(reading.date));if(!vo2Weeks.has(week))vo2Weeks.set(week,[]);vo2Weeks.get(week).push(reading.value)}
  const vo2=[...vo2Weeks].sort((a,b)=>a[0].localeCompare(b[0])).map(([date,values])=>({date,value:values.reduce((sum,n)=>sum+n,0)/values.length,count:values.length}));
