  const weekBeginning=weekStart(todayISO()),weekEnding=new Date(weekBeginning);weekEnding.setDate(weekEnding.getDate()+7);
  const thisWeekRuns=state.runs.filter(r=>{const date=new Date(`${r.date}T12:00:00`);return date>=weekBeginning&&date<weekEnding}).length;
  const nextRun=RUN_PLAN[thisWeekRuns]||null,targets=runningTargets();
