function openProgramDay(number){const day=state.program[number-1];if(!day)return;const date=weekDate(number),root=$('#program-overlay-root');root.innerHTML=`<div class="program-backdrop" id="program-backdrop"><section class="program-overlay" role="dialog" aria-modal="true" aria-label="Day ${number} full program"><div class="overlay-header"><div><div class="eyebrow">DAY ${number} / ${esc(day.goal)}</div><h2>${esc(day.focus)}</h2><p>${day.exercises.length} exercises · ${esc(pretty(date))}</p></div><button class="overlay-close" id="overlay-close" aria-label="Close program">×</button></div><div class="overlay-exercises">${day.exercises.map((ex,i)=>`<article class="overlay-exercise"><img src="assets/${esc(ex.image)}" alt="${esc(ex.name)}"><div><span class="eyebrow">${String(i+1).padStart(2,'0')} · ${esc(ex.unit)}</span><h3>${esc(ex.name)}</h3><p>${esc(ex.cue)}</p></div><strong>${ex.sets} × ${esc(ex.target)}</strong></article>`).join('')}</div><div class="overlay-footer"><span>${number===4?'Use a sturdy chair for assisted pistols.':'Work with controlled form and rest between sets.'}</span><button class="button dark" id="overlay-log">${activityFor(date,number)?'Edit':'Log'} this day ↗</button></div></section></div>`;if(day.trainingInstructions)root.querySelector('.overlay-footer').insertAdjacentHTML('beforebegin',programGuidance(day));document.body.classList.add('overlay-open');$('#overlay-close').addEventListener('click',closeProgramDay);$('#program-backdrop').addEventListener('click',e=>{if(e.target.id==='program-backdrop')closeProgramDay()});$('#overlay-log').addEventListener('click',()=>{closeProgramDay();openWorkout(number,date)})}
