function programGuidance(day){return day.trainingInstructions?`<div class="program-guidance"><strong>Training notes</strong><p>${esc(day.equipment||'')}</p><p>${esc(day.trainingInstructions)}</p>${day.note?`<p class="program-limitation">${esc(day.note)}</p>`:''}</div>`:''}
