  const best5kTime=Math.min(...runs.flatMap(r=>[Number.isFinite(r.best5kSeconds)?r.best5kSeconds:null,Math.abs(r.distanceKm-5)<=.075?r.durationSeconds:null,Number.isFinite(r.best5kSeconds)||paceSeconds(r.bestPaces?.['5km'])===null?null:Math.round(paceSeconds(r.bestPaces['5km'])*5)].filter(Number.isFinite)));
