  main.innerHTML=`<div class="page-head"><div><div class="eyebrow">YOUR RUNNING ROUTINE</div><h1>Running</h1><p>Three repeatable sessions. No fixed week-by-week distance plan.</p></div></div><section class="cal-hero run-hero"><div><span class="eyebrow light">THREE RUNS · FLEXIBLE DAYS</span><h2>Run your way, improve your pace</h2><p>One easy long run, one interval session, and one steady pace run.</p></div><div class="cal-hero-actions"><button class="button" id="run-log">Log a run ↗</button></div></section><section class="metrics endurance-metrics"><div class="metric"><span class="metric-label">Runs logged</span><strong>${runs.length}</strong><small>In your Excel log</small></div><div class="metric"><span class="metric-label">Distance</span><strong>${km.toFixed(1)}<small> km</small></strong><small>In ${selectedYear}</small></div><div class="metric"><span class="metric-label">Best 5 km</span><strong class="metric-text">${best5k===null?'—':durationText(best5kTime)}</strong><small>${best5k===null?'No 5 km split yet':`${paceLabel(best5k)}/km best-effort pace`}</small></div></section><h2 class="section-title">Your three runs</h2><div class="program-grid run-program-grid">${cards}</div><div class="two-col cal-bottom">${chartPanel('Recent runs',`${selectedYear} sessions`,recent.length?`<div class="record-list">${recent}</div>`:`<div class="empty">Your runs will appear here after you log them.</div>`)}${chartPanel('Best distances','From saved runs and splits',`<div class="best-list">${runningBests()}</div><p class="small-muted">Strava best-effort times can differ from a run’s moving time.</p>`)}</div>`;
  $('#run-log').addEventListener('click',()=>openEndurance('running'));
