function renderCyclingOverview(){
  const rides=state.rides.filter(inSelectedYear).sort((a,b)=>b.date.localeCompare(a.date));
  const km=rides.reduce((sum,r)=>sum+r.distanceKm,0);
  const latest=rides[0];
  const recent=rides.slice(0,5).map(r=>`<div class="record"><div><div class="record-name">${r.distanceKm} km · ${durationText(r.durationSeconds)}</div><div class="record-meta">${esc(pretty(r.date))}${r.route?` · ${esc(r.route)}`:''}</div></div><button class="text-button edit-ride" data-id="${esc(r.id)}">Open ↗</button></div>`).join('');
  main.innerHTML=`<div class="page-head"><div><div class="eyebrow">YOUR CYCLING</div><h1>Cycling</h1><p>Every ride in one place, with your distance and time saved to Excel.</p></div></div><section class="cal-hero cycling-hero"><div><span class="eyebrow light">RIDES · DISTANCE · TIME</span><h2>Keep the wheels turning</h2><p>See your rides and add the next one when you’re ready.</p></div><div class="cal-hero-actions"><button class="button" id="ride-log">Log a ride ↗</button></div></section><section class="metrics endurance-metrics"><div class="metric"><span class="metric-label">Rides logged</span><strong>${rides.length}</strong><small>In your Excel log</small></div><div class="metric"><span class="metric-label">Distance</span><strong>${km.toFixed(1)}<small> km</small></strong><small>In ${selectedYear}</small></div><div class="metric"><span class="metric-label">Longest ride</span><strong class="metric-text">${rides.length?`${Math.max(...rides.map(r=>r.distanceKm)).toFixed(1)} km`:'—'}</strong><small>Single journey</small></div></section><h2 class="section-title">Your rides</h2><div class="two-col cycling-overview"><article class="cycling-feature"><img src="assets/cycling-ride.webp" alt="Cyclist riding beside the Helsinki waterfront"><div><span class="eyebrow">LATEST RIDE</span><h3>${latest?`${latest.distanceKm} km · ${durationText(latest.durationSeconds)}`:'Your next ride starts here'}</h3><p>${latest?`${esc(pretty(latest.date))}${latest.route?` · ${esc(latest.route)}`:''}`:'Log your first ride to see it here.'}</p><button class="button dark" id="ride-feature-log">Log a ride ↗</button></div></article>${chartPanel('Recent rides',`${selectedYear} journeys`,recent?`<div class="record-list">${recent}</div>`:`<div class="empty">Your rides will appear here after you log them.</div>`)}</div>`;
  $('#ride-log').addEventListener('click',()=>openEndurance('cycling'));
  $('#ride-feature-log').addEventListener('click',()=>openEndurance('cycling'));
  main.querySelectorAll('.edit-ride').forEach(button=>button.addEventListener('click',()=>openEndurance('cycling',button.dataset.id)));
}
function openEndurance(kind,id=null){enduranceEdit=null;runningFormOpen=false;cyclingFormOpen=false;nav(kind)}
function fitnessFields(old){return `<div class="fitness-fields wide"><div class="eyebrow">FITNESS READINGS · OPTIONAL</div><p>Enter values from your watch or another measurement. VO₂ max appears on Home.</p><div class="fitness-inputs"><label class="field">Average workout HR (bpm)<input id="end-avg-hr" type="number" min="30" max="250" step="1" value="${old?.avgHr??''}" placeholder="e.g. 145"></label><label class="field">Resting HR (bpm)<input id="end-resting-hr" type="number" min="25" max="150" step="1" value="${old?.restingHr??''}" placeholder="e.g. 58"></label><label class="field">VO₂ max (ml/kg/min)<input id="end-vo2" type="number" min="10" max="120" step="0.1" value="${old?.vo2max??''}" placeholder="e.g. 42.5"></label></div></div>`}
function renderEndurance(kind){
  const running=kind==='running',entries=running?state.runs:state.rides,old=entries.find(x=>x.id===enduranceEdit);
  const title=running?'Running':'Cycling',noun=running?'run':'ride';
  const totalKm=entries.reduce((sum,x)=>sum+x.distanceKm,0),best=entries.length?(running?Math.min(...entries.map(x=>x.durationSeconds/x.distanceKm)):Math.max(...entries.map(x=>x.distanceKm/(x.durationSeconds/3600)))):null;
  const bestText=best===null?'—':running?paceText({durationSeconds:best,distanceKm:1}):`${best.toFixed(1)} km/h`;
  const seconds=old?.durationSeconds||0,hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60),secs=seconds%60;
  const recent=[...entries].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5);
  main.innerHTML=`${`<button class="text-button" id="back-endurance">← ${title} overview</button>`}<div class="page-head"><div><div class="eyebrow">ENDURANCE LOG</div><h1>${old?`Edit ${noun}`:`Log a ${noun}`}</h1><p>One simple entry for each ${noun}. Saved to its own Excel sheet.</p></div></div>
    <section class="metrics endurance-metrics"><div class="metric"><span class="metric-label">Total ${noun}s</span><strong>${entries.length}</strong><small>Saved activities</small></div><div class="metric"><span class="metric-label">Distance</span><strong>${totalKm.toFixed(1)}<small> km</small></strong><small>All time</small></div><div class="metric"><span class="metric-label">Best ${running?'pace':'average speed'}</span><strong class="metric-text">${bestText}</strong><small>${running?'Lower is faster':'Higher is faster'}</small></div></section>
    <section class="panel"><div class="panel-head"><h2>${old?`Edit ${noun}`:`Log a ${noun}`}</h2><span class="panel-sub">${running?'Distance · time · pace':'Distance · time · speed'}</span></div><form id="endurance-form"><div class="endurance-fields"><label class="field">Date<input id="end-date" type="date" min="2026-01-01" max="2028-12-31" required value="${esc(old?.date||todayISO())}"></label><label class="field">Distance (km)<input id="end-distance" type="number" min="${running?0.01:0}" max="2000" step="0.01" inputmode="decimal" required value="${old?.distanceKm??''}" placeholder="e.g. 5.00"></label><div class="field"><span>Duration</span><div class="duration-fields"><label><input id="end-hours" type="number" min="0" max="167" step="1" inputmode="numeric" value="${hours}" aria-label="Hours"><small>hours</small></label><label><input id="end-minutes" type="number" min="0" max="59" step="1" inputmode="numeric" value="${minutes}" aria-label="Minutes"><small>minutes</small></label><label><input id="end-seconds" type="number" min="0" max="59" step="1" inputmode="numeric" value="${secs}" aria-label="Seconds"><small>seconds</small></label></div></div>${running?'':`<label class="field">Elevation gain (m) <span class="optional">optional</span><input id="end-elevation" type="number" min="0" max="20000" step="1" inputmode="numeric" value="${old?.elevationM??''}" placeholder="e.g. 320"></label>`}<label class="field">Route <span class="optional">optional</span><input id="end-route" type="text" maxlength="200" value="${esc(old?.route||'')}" placeholder="Where did you go?"></label><label class="field">Effort<select id="end-effort"><option value="">Choose effort</option>${['Easy','Moderate','Hard','Race'].map(x=>`<option value="${x}" ${old?.effort===x?'selected':''}>${x}</option>`).join('')}</select></label>${running?`<label class="field">Run type<select id="end-run-type"><option value="">Choose type</option>${["Easy long","Intervals","Steady"].map(x=>`<option value="${x}" ${old?.runType===x?"selected":""}>${x}</option>`).join("")}</select></label><label class="field">Interval rep pace (min:sec/km) <span class="optional">optional</span><input id="end-interval-pace" type="text" inputmode="numeric" pattern="[0-9]{1,2}:[0-5][0-9]" value="${esc(old?.intervalPace||"")}" placeholder="e.g. 5:20"></label>`:""}<label class="field wide">Notes <span class="optional">optional</span><textarea id="end-notes" maxlength="1000" placeholder="Anything you want to remember">${esc(old?.notes||'')}</textarea></label>${fitnessFields(old)}</div><div class="save-row"><span class="save-help">Pace or average speed is calculated for you. The entry goes into the ${title} Log worksheet.</span><button class="button dark" type="submit" id="end-save">${old?'Update':'Save'} ${noun} to Excel ↗</button></div></form></section>
    ${running?`<section class="panel running-bests-panel"><div class="panel-head"><h2>Best distance splits</h2><span class="panel-sub">From the paces you supplied · time and pace shown</span></div><div class="best-list">${runningBests()}</div></section>`:""}
    <section><h2 class="section-title">Recent ${noun}s</h2>${recent.length?`<div class="activity-list">${recent.map(x=>`<article class="activity"><div><div class="eyebrow">${esc(pretty(x.date))}</div><div class="activity-title">${x.distanceKm} km · ${durationText(x.durationSeconds)}</div><div class="activity-meta">${running?paceText(x):`${(x.distanceKm/(x.durationSeconds/3600)).toFixed(1)} km/h`}${x.route?` · ${esc(x.route)}`:''}</div></div><button class="button secondary small edit-endurance" data-id="${esc(x.id)}">Edit ↗</button></article>`).join('')}</div>`:`<div class="panel empty">No ${noun}s logged yet. Enter your first one above.</div>`}</section>`;
  $('#endurance-form').addEventListener('submit',event=>saveEndurance(event,kind));
  $('#back-endurance')?.addEventListener('click',()=>{runningFormOpen=false;cyclingFormOpen=false;enduranceEdit=null;nav(kind)});
  main.querySelectorAll('.edit-endurance').forEach(button=>button.addEventListener('click',()=>openEndurance(kind,button.dataset.id)));
}
function saveEndurance(event){event.preventDefault()}
function renderActivities(){const sorted=allEntries().filter(inSelectedYear).sort((a,b)=>b.date.localeCompare(a.date)||a.type.localeCompare(b.type));
  const card=a=>{if(a.type==='calisthenics'){const day=state.program[a.day-1];const highlights=day.exercises.map(ex=>({ex,score:bestOf(a,ex)})).filter(x=>x.score!==null).slice(0,4);return `<article class="activity"><div><div class="eyebrow">${esc(pretty(a.date))} · CALISTHENICS / DAY ${a.day}</div><div class="activity-title">${esc(day.focus)}</div><div class="activity-meta">${setCount(a)} set values · Form: ${esc(a.form||'not rated')}</div><div class="activity-detail">${highlights.map(x=>`<span>${esc(x.ex.name)} ${x.score} ${esc(x.ex.unit)} · ${esc(rankFor(a,x.ex))}</span>`).join('')}</div></div><div class="activity-right"><button class="button secondary small edit-activity" data-day="${a.day}" data-date="${a.date}">View ↗</button></div></article>`}
    const running=a.type==='running';return `<article class="activity"><div><div class="eyebrow">${esc(pretty(a.date))} · ${running?'RUNNING':'CYCLING'}</div><div class="activity-title">${a.distanceKm} km · ${durationText(a.durationSeconds)}</div><div class="activity-meta">${running?paceText(a):`${(a.distanceKm/(a.durationSeconds/3600)).toFixed(1)} km/h`}${a.route?` · ${esc(a.route)}`:''}${!running&&a.elevationM!==null?` · ${a.elevationM} m climbed`:''}</div></div><div class="activity-right"><button class="button secondary small edit-endurance" data-kind="${a.type}" data-id="${esc(a.id)}">View ↗</button></div></article>`};
  main.innerHTML=`<div class="page-head"><div><div class="eyebrow">YOUR TRAINING HISTORY</div><h1>Activities</h1><p>Calisthenics, running and cycling in ${selectedYear}.</p></div></div>${sorted.length?`<div class="activity-list">${sorted.map(card).join('')}</div>`:`<div class="panel empty">No activities in ${selectedYear}. Save a workout, run or ride to see it here.</div>`}`;
  main.querySelectorAll('.edit-activity').forEach(button=>button.addEventListener('click',()=>openWorkout(Number(button.dataset.day),button.dataset.date)));
  main.querySelectorAll('.edit-endurance').forEach(button=>button.addEventListener('click',()=>openEndurance(button.dataset.kind,button.dataset.id)));
}

function render(){renderWeekDots();if(view==='home')renderHome();else if(view==='calisthenics')renderCalisthenics();else if(view==='workout')renderWorkout();else if(view==='running'&&!runningFormOpen)renderRunningOverview();else if(view==='cycling'&&!cyclingFormOpen)renderCyclingOverview();else if(view==='running'||view==='cycling')renderEndurance(view);else renderActivities()}
async function loadState(){const response=await fetch('data/state.json',{cache:'no-store'});if(!response.ok)throw new Error('Could not read the Excel log');state=await response.json()}
document.querySelectorAll('[data-view]').forEach(button=>button.addEventListener('click',()=>{enduranceEdit=null;runningFormOpen=false;cyclingFormOpen=false;nav(button.dataset.view)}));
$('#year-filter').addEventListener('change',event=>{selectedYear=Number(event.target.value);localStorage.setItem('trainingYear',String(selectedYear));$('#crumb').textContent=(view==='workout'?`WORKOUT / DAY ${workoutDay}`:`${view.toUpperCase()} / ${selectedYear}`);if(view==='workout'||runningFormOpen||cyclingFormOpen)return;render()});
document.querySelectorAll('#week-dots button').forEach(button=>button.addEventListener('click',()=>openProgramDay(Number(button.dataset.day))));
try{await loadState();$('#crumb').textContent=`HOME / ${selectedYear}`;render()}catch(error){main.innerHTML=`<div class="panel"><h1>Could not open the training log</h1><p class="error">${esc(error.message)}</p><p>Keep the local website launcher running, then reload this page.</p></div>`;$('#save-status').textContent='Snapshot unavailable'}
